def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 40.0))
        return float(min(budget, 18.0))

    prev_bids = []
    urgent_prev_bids = []
    max_req = WATER_REQ
    for opp in alive_opponents:
        req = opp.get('water_requirement', WATER_REQ)
        if req > max_req:
            max_req = req
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_prev_bids) if urgent_prev_bids else highest_prev

    tight_supply = supply <= float(WATER_REQ + max_req)
    very_tight = supply <= float(WATER_REQ)

    base = 22.0
    if highest_prev > 0:
        base = max(base, highest_prev + 2.0)

    if hp <= 2 or no_water_days >= 1:
        bid = max(base, urgent_high + 4.0, 92.0)
    elif hp <= 4:
        bid = max(base, 72.0 if tight_supply else 58.0)
    else:
        if very_tight:
            bid = max(base, 84.0)
        elif tight_supply:
            bid = max(base, 64.0)
        else:
            bid = max(28.0, min(52.0, highest_prev * 0.72 if highest_prev > 0 else 36.0))

    if budget < bid:
        if hp <= 2 or no_water_days >= 1:
            return float(budget)
        return float(max(0.0, budget))

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, bid to cover requirement.
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline from observed behavior.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    lowest_prev_bid = min(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely available; use to scale aggressiveness.
    # (We only need a rough pressure signal.)
    supply_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if supply_units < 1:
        supply_units = 1

    # Determine target bid level.
    # If my HP is critical, I must secure water.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        # Aggressive: bid near/above yesterday leader but cap by budget.
        target = max(highest_prev_bid * 0.98, DAILY_SALARY * 0.85)
    else:
        # Otherwise, try to outbid the lower-mid competitor (Eric-like behavior) rather than the leader.
        # Use supply to decide whether to be more or less aggressive.
        if supply >= 20.0:
            # High supply: leader may be overbidding; still bid slightly above typical mid.
            target = max(DAILY_SALARY * 0.62, lowest_prev_bid + 10.0)
        else:
            # Moderate supply: push closer to leader if they likely contest.
            target = max(DAILY_SALARY * 0.55, lowest_prev_bid + 7.0)

        # If yesterday leader was extremely high, avoid getting undercut.
        if highest_prev_bid >= DAILY_SALARY * 1.15:
            target = max(target, highest_prev_bid * 0.9)

    # Ensure we don't exceed budget and keep within reasonable bounds.
    # Also avoid bidding too low when supply is tight.
    tight_supply = (supply <= 16.5)
    if tight_supply:
        target = max(target, DAILY_SALARY * 0.7)

    bid = min(my_budget, max(0.0, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    supply = day_context['supply']

    CRITICAL_HP = 2 
    LOW_HP = 4      
    MEDIUM_HP = 7   

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    target_bid = 0.0

    if my_hp <= CRITICAL_HP:
        target_bid = DAILY_SALARY * 0.95
    elif my_hp <= LOW_HP:
        target_bid = DAILY_SALARY * 0.85
    elif my_hp <= MEDIUM_HP:
        target_bid = DAILY_SALARY * 0.7
    else:
        target_bid = DAILY_SALARY * 0.6

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_hp <= LOW_HP:
            target_bid = max(target_bid, highest_prev_bid + 2.5)
        else:
            target_bid = max(target_bid, highest_prev_bid + 1.0)

    if current_day >= EPISODE_DAYS - 2:
        if my_hp <= LOW_HP:
            target_bid = max(target_bid, DAILY_SALARY * 0.98)
        else:
            target_bid = max(target_bid, DAILY_SALARY * 0.9)
    elif current_day >= EPISODE_DAYS - 4:
        if my_hp <= MEDIUM_HP:
            target_bid = max(target_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_budget, target_bid)

    if my_hp <= CRITICAL_HP and my_budget < target_bid:
        final_bid = my_budget

    if final_bid < 1.0 and my_budget > 0:
        final_bid = 1.0

    return final_bid
